from interops.libraries.squish_actions import CommonActions
from interops.libraries.xvi.interactions.objects.xvi_core_objects import Xvi_MainPage
from interops.libraries.xvi.interactions.objects.xvi_patient_objects import Xvi_Patient_page
from ..interactions import new_patient_reg

def open_new_patient_and_enter_mandetory_id(patientId:str) -> None:
    """Enter Mandetory ID on the New patients window
    patientId
    """
    new_patient_reg.open_patient_newPage()
    new_patient_reg.typeText_in_patient_id(patientId)

def enter_patient_name(patientLastName: str, patientFirstName: str ,patientMiddleName:str) -> None:
    """Enter Name details on the New patients window
    patientFirstName,patientLastName,patientMiddleName
    """
    new_patient_reg.typeText_in_patient_first_name(patientFirstName)
    new_patient_reg.typeText_in_patient_last_name(patientLastName)
    new_patient_reg.typeText_in_patient_middle_name(patientMiddleName)

def enter_personal_details(patientDOB:str,patientAddress:str,patientPhone:str,patientSex:str) -> None:
    """Enter personal details on the New patients window
    patientDOB,patientAddress,patientPhone,patientSex
    """
    new_patient_reg.typeText_in_patient_station("Default")
    new_patient_reg.typeText_in_patient_birth_date(patientDOB)
    new_patient_reg.typeText_in_patient_address(patientAddress)
    new_patient_reg.typeText_in_patient_phone(patientPhone)
    new_patient_reg.select_Patients_sex(patientSex)

def enter_physician_details(patientPrimary:str,patientPrimaryPhone:str,patientAlternate:str,patientAlternatePhone:str,comments:str,inactive:bool) -> None:
    """Enter physician the fields on the New patients window
    patientPrimary,patientPrimaryPhone,patientAlternate,patientAlternatePhone,comments,inactive
    """
    new_patient_reg.typeText_in_patient_physician_primaryDetail(patientPrimary)
    new_patient_reg.typeText_in_patient_physician_alternateDetails(patientAlternate)
    new_patient_reg.typeText_in_patient_physicianprimaryphone(patientPrimaryPhone)
    new_patient_reg.typeText_in_patient_physicianalternatePhone(patientAlternatePhone)
    new_patient_reg.typeText_in_patient_comment(comments)
    if inactive:
        new_patient_reg.select_inactive()
    new_patient_reg.clickOK()
    new_patient_reg.click_ok_duplicatePatients()